/** Owned read seam for project other-fee GenericResource routes. */
@RestController
@ConditionalOnBean({OwnedIdentityHttpBoundary.class, DataSource.class})
public final class OwnedProjectOtherFeeQueryController {
    private static final String PREFIX = "/secure/emc/module/bp/project/other-fees";
    private final OwnedIdentityHttpBoundary boundary;
    private final DataSource dataSource;
    public OwnedProjectOtherFeeQueryController(OwnedIdentityHttpBoundary boundary, DataSource dataSource) { if(boundary==null||dataSource==null)throw new IllegalArgumentException("other-fee dependencies are required");this.boundary=boundary;this.dataSource=dataSource; }
    @GetMapping(path=PREFIX+"/info/status",produces=MediaType.APPLICATION_JSON_VALUE)
    public ResponseEntity<String> status(HttpServletRequest request){try{require(request);return ok("{\"ext$\":{}}");}catch(AccessDeniedException e){return forbidden();}catch(SQLException e){return unavailable();}}
    @PostMapping(path={PREFIX+"/queries",PREFIX+"/queries/raw",PREFIX+"/queries/searchable"},consumes=MediaType.APPLICATION_JSON_VALUE,produces=MediaType.APPLICATION_JSON_VALUE)
    public ResponseEntity<String> query(HttpServletRequest request,@RequestBody(required=false)String body){try{OwnedPrincipal p=require(request);return ok(selectPage(p.getOrgId(),Page.parse(body)));}catch(AccessDeniedException e){return forbidden();}catch(IllegalArgumentException e){return badRequest();}catch(SQLException e){return unavailable();}}
    private OwnedPrincipal require(HttpServletRequest request)throws SQLException{boundary.requirePermission(request.getSession(false),OwnedIdentityProvider.RESULT_READ);return boundary.currentPrincipal(request.getSession(false));}
    private String selectPage(String org,Page page)throws SQLException{String source="SELECT T.* FROM T_EMC_PROJECT_OTHER_FEE T JOIN T_EMC_PROJECT P ON P.ID=T.PROJID WHERE P.CREATEDBYORGID=?"+page.where;List<Object> params=new ArrayList<Object>();params.add(org);params.addAll(page.values);String count="SELECT COUNT(1) FROM ("+source+") Q";String sql="SELECT X.* FROM (SELECT Q.*,ROW_NUMBER() OVER (ORDER BY "+page.order+") RN_ FROM ("+source+") Q) X WHERE X.RN_>? AND X.RN_<=? ORDER BY X.RN_";int total;List<Map<String,Object>>rows=new ArrayList<Map<String,Object>>();Map<String,String>types=new LinkedHashMap<String,String>();try(Connection c=dataSource.getConnection()){try(PreparedStatement s=c.prepareStatement(count)){bind(s,params);try(ResultSet r=s.executeQuery()){if(!r.next())throw new SQLException("other-fee count unavailable");total=r.getInt(1);}}try(PreparedStatement s=c.prepareStatement(sql)){int next=bind(s,params);s.setInt(next++,page.start());s.setInt(next,page.end());try(ResultSet r=s.executeQuery()){ResultSetMetaData m=r.getMetaData();for(int i=1;i<=m.getColumnCount();i++){String n=m.getColumnLabel(i);if(!"RN_".equalsIgnoreCase(n))types.put(n.toLowerCase(Locale.ROOT),type(m.getColumnType(i)));}while(r.next())rows.add(row(r,m));}}}Map<String,Object>e=new LinkedHashMap<String,Object>();e.put("columnTypeMap",types);e.put("first",page.number==1);e.put("last",total==0||page.number>=pages(total,page.size));e.put("numberOfElements",rows.size());e.put("pageNumber",page.number);e.put("pageSize",page.size);e.put("rows",rows);e.put("total",total);Map<String,Object>tm=new LinkedHashMap<String,Object>();tm.put("qty_",total);e.put("totalMap",tm);e.put("totalPages",pages(total,page.size));return JSON.toJSONString(e,SerializerFeature.WriteMapNullValue);}
    private static Map<String,Object>row(ResultSet r,ResultSetMetaData m)throws SQLException{Map<String,Object>v=new LinkedHashMap<String,Object>();for(int i=1;i<=m.getColumnCount();i++){String n=m.getColumnLabel(i);if(!"RN_".equalsIgnoreCase(n))v.put(camel(n),JdbcValue.normalize(r.getObject(i)));}v.put("ext$",new LinkedHashMap<String,Object>());return v;}
    private static String camel(String n){String s=n.toLowerCase(Locale.ROOT),compact=s.replace("_","");if("projid".equals(compact))return"projId";if("feetype".equals(compact))return"feeType";if("feename".equals(compact))return"feeName";if("feesingleprice".equals(compact))return"feeSinglePrice";if("feecount".equals(compact))return"feeCount";return s.indexOf('_')<0?compact:toCamel(s);}
    private static String toCamel(String s){StringBuilder b=new StringBuilder();boolean u=false;for(char c:s.toCharArray()){if(c=='_'){u=true;continue;}b.append(u?Character.toUpperCase(c):c);u=false;}return b.toString();}
    private static String type(int t){return t==Types.DATE||t==Types.TIMESTAMP||t==Types.TIMESTAMP_WITH_TIMEZONE?"dateTime":(t==Types.NUMERIC||t==Types.DECIMAL||t==Types.INTEGER||t==Types.BIGINT?"number":"string");}private static int pages(int t,int s){return t==0?0:(t+s-1)/s;}private static ResponseEntity<String>ok(String b){return ResponseEntity.ok().contentType(MediaType.APPLICATION_JSON).body(b);}private static ResponseEntity<String>forbidden(){return ResponseEntity.status(HttpStatus.FORBIDDEN).contentType(MediaType.APPLICATION_JSON).body("{\"message\":\"GIKAM.PERMISSION.UNAUTHORIZED\"}");}private static ResponseEntity<String>badRequest(){return ResponseEntity.badRequest().contentType(MediaType.APPLICATION_JSON).body("{\"message\":\"GIKAM.PROJECT_OTHER_FEE.INVALID_QUERY\"}");}private static ResponseEntity<String>unavailable(){return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).contentType(MediaType.APPLICATION_JSON).body("{\"message\":\"GIKAM.PROJECT_OTHER_FEE.UNAVAILABLE\"}");}
    private static int bind(PreparedStatement statement,List<Object> values)throws SQLException{int index=1;for(Object value:values)statement.setObject(index++,value);return index;}
    private static final class Page{final int number,size;final String where,order;final List<Object> values;Page(int n,int s,String w,String o,List<Object> v){number=n;size=s;where=w;order=o;values=Collections.unmodifiableList(v);}static Page parse(String b){QueryRequest request=QueryRequest.parse(b,null);if(!request.getAdvancedPatterns().isEmpty()||request.getMultiPropertyPattern()!=null)throw new IllegalArgumentException("advanced other-fee filters are unsupported");Map<String,String> fields=new LinkedHashMap<String,String>();fields.put("ID","T.ID");fields.put("PROJID","T.PROJID");fields.put("FEETYPE","T.FEETYPE");fields.put("FEENAME","T.FEENAME");fields.put("FEESINGLEPRICE","T.FEESINGLEPRICE");fields.put("FEECOUNT","T.FEECOUNT");fields.put("AMOUNT","T.AMOUNT");fields.put("STATUS","T.STATUS");StringBuilder where=new StringBuilder();List<Object> values=new ArrayList<Object>();for(Map.Entry<String,Object> e:request.getMapperParameters().entrySet()){String col=fields.get(e.getKey().toUpperCase(Locale.ROOT));if(col==null)throw new IllegalArgumentException("unsupported other-fee field: "+e.getKey());append(where,values,col,"EQ",e.getValue());}for(FilterParamPattern filter:request.getFilterPatterns())for(Map.Entry<String,Object> e:filter.getMap().entrySet()){String col=fields.get(e.getKey().toUpperCase(Locale.ROOT));if(col==null)throw new IllegalArgumentException("unsupported other-fee filter: "+e.getKey());append(where,values,col,filter.getMatchPattern(),e.getValue());}Map<String,String> orders=new LinkedHashMap<String,String>();orders.putAll(fields);StringBuilder order=new StringBuilder();for(Pair<String,String> pair:request.getOrderParameters()){String col=orders.get(String.valueOf(pair.getFirst()).toUpperCase(Locale.ROOT));if(col==null)throw new IllegalArgumentException("unsupported other-fee order: "+pair.getFirst());if(order.length()>0)order.append(',');order.append(col).append("desc".equalsIgnoreCase(pair.getSecond())?" DESC":" ASC");}if(order.length()==0)order.append("T.ID DESC");return new Page(request.getPageNumber(),request.getPageSize(),where.toString(),order.toString(),values);}private static void append(StringBuilder where,List<Object> values,String col,String pattern,Object raw){MatchPattern p=MatchPattern.getPatternIfPossible(pattern==null?"":pattern.toUpperCase(Locale.ROOT));if(p==null)throw new IllegalArgumentException("unsupported other-fee pattern: "+pattern);if(p==MatchPattern.ISNULL){where.append(" AND ").append(col).append(" IS NULL");return;}if(p==MatchPattern.ISNOTNULL){where.append(" AND ").append(col).append(" IS NOT NULL");return;}if(p==MatchPattern.IN||p==MatchPattern.OR||p==MatchPattern.OIN){List<Object> list=values(raw);if(list.isEmpty()){where.append(" AND 1=0");return;}where.append(" AND (");for(int i=0;i<list.size();i++){if(i>0)where.append(" OR ");where.append(col).append("=?");values.add(list.get(i));}where.append(')');return;}if(p==MatchPattern.EQ||p==MatchPattern.SEQ){where.append(" AND ").append(col).append("=?");values.add(raw);return;}if(p==MatchPattern.DIFFER){where.append(" AND ").append(col).append("<>?");values.add(raw);return;}String text=raw==null?null:String.valueOf(raw);if(p==MatchPattern.SB||p==MatchPattern.CBM){where.append(" AND ").append(col).append(" LIKE ?");values.add(text+"%");return;}if(p==MatchPattern.SC){where.append(" AND ").append(col).append(" LIKE ?");values.add("%"+text+"%");return;}if(p==MatchPattern.SE){where.append(" AND ").append(col).append(" LIKE ?");values.add("%"+text);return;}if(p==MatchPattern.CISB||p==MatchPattern.CISC||p==MatchPattern.CISE){where.append(" AND UPPER(").append(col).append(") LIKE UPPER(?)");values.add(p==MatchPattern.CISB?text+"%":p==MatchPattern.CISC?"%"+text+"%":"%"+text);return;}String op=p==MatchPattern.NG?">":p==MatchPattern.NGOE?">=":p==MatchPattern.NL?"<":p==MatchPattern.NLOE?"<=":p==MatchPattern.NEQ?"=":null;if(op!=null){where.append(" AND ").append(col).append(op).append('?');values.add(raw);return;}throw new IllegalArgumentException("unsupported other-fee pattern: "+pattern);}private static List<Object> values(Object raw){if(raw instanceof Collection<?>)return new ArrayList<Object>((Collection<?>)raw);if(raw==null)return Collections.emptyList();String text=String.valueOf(raw);if(text.startsWith("[")&&text.endsWith("]")){try{return new ArrayList<Object>(JSON.parseArray(text));}catch(RuntimeException ignored){throw new IllegalArgumentException("invalid list filter");}}if(text.indexOf(',')<0)return Collections.<Object>singletonList(raw);List<Object> result=new ArrayList<Object>();for(String item:text.split(",",-1))if(!item.trim().isEmpty())result.add(item.trim());return result;}int start(){return(number-1)*size;}int end(){return number*size;}}
}
